import {
    Expression,
    FieldIndex,
    GazeStyle,
    MotionMode,
} from "../face-engine/faceConfigTypes";
import type { FaceConfigState } from "../face-engine/faceConfigState";
import type { IdleAnimRow } from "../face-engine/faceConfigTypes";
import {
    bobAmpCppLiteral,
    emitFacePRowCpp,
    expressionToFirmwareSlug,
    fieldIndexEnumName,
    fmtCppFloat,
    namedEmotionEnumName,
} from "./format";

const FACE_ENUM_PREAMBLE = `#pragma once

/**
 * @file FACE_CONFIG_DATA.h
 * @brief Editor-exportable face data. Generated by face-editor POST /api/saveData.
 *
 * Generated by face-editor POST /api/saveData. Firmware helpers live in \`FACE_CONFIG.h\`.
 */

#include "FacePrimitives.h"

namespace Face {

enum class Expression : uint8_t {
  Neutral = 0,
  Happy,
  Excited,
  Joyful,
  Sad,
  VerbThinking,
  VerbReading,
  VerbWriting,
  VerbExecuting,
  VerbStraining,
  VerbSleeping,
  OverlayWaking,
  OverlayAttention,
  Sleepy,
  Distressed,
  Blissed,
  Depressed,
  Shocked,
  Disappointed,
  Cheeky,
  Gleeful,
  Frustrated,
  Count
};

}  // namespace Face

namespace EmotionSystem {

enum class NamedEmotion : uint8_t {
  Neutral = 0,
  Happy,
  Excited,
  Joyful,
  Sad,
  Sleepy,
  Distressed,
  Blissed,
  Depressed,
  Shocked,
  Disappointed,
  Cheeky,
  Gleeful,
  Frustrated,
  Count
};

}  // namespace EmotionSystem

namespace FaceConfig {
`;

function emitExpressionNames(expressions: string[]): string {
    const slugs = expressions.map(expressionToFirmwareSlug);
    const lines: string[] = [];
    for (let i = 0; i < slugs.length; i += 6) {
        lines.push("    " + slugs.slice(i, i + 6).map(s => `"${s}"`).join(", ") + ",");
    }
    return `static constexpr const char* kExpressionNames[(size_t)Face::Expression::Count] = {\n${lines.join("\n")}\n};`;
}

function emitPickOrder(config: FaceConfigState): string {
    const lines = config.pickOrderIndices.map(
        i =>
            `    EmotionSystem::NamedEmotion::${namedEmotionEnumName(config.emotionNames[i]!)}`
    );
    return `static constexpr EmotionSystem::NamedEmotion kPickOrder[] = {\n${lines.join(",\n")},\n};`;
}

function emitNamedEmotionToExpression(config: FaceConfigState): string {
    const lines: string[] = [];
    let row: string[] = [];
    for (let i = 0; i < config.namedEmotionToExpressionIndex.length; i++) {
        const ex = config.expressions[config.namedEmotionToExpressionIndex[i]!]!;
        row.push(`Face::Expression::${ex}`);
        if (row.length === 3) {
            lines.push("    " + row.join(", ") + ",");
            row = [];
        }
    }
    if (row.length) lines.push("    " + row.join(", ") + ",");
    return `static constexpr Face::Expression
    kNamedEmotionToExpression[(size_t)EmotionSystem::NamedEmotion::Count] = {
${lines.join("\n")}
};`;
}

function emitVerbTimelines(config: FaceConfigState): string {
    const blocks: string[] = [];
    for (const tab of config.verbTimelines) {
        const verbName = Expression[tab.verb];
        const kfBlocks: string[] = [];
        for (const kf of tab.keyframes) {
            const ko = kf.overrides
                .map(
                    o =>
                        `             KO(Face::FieldIndex::${fieldIndexEnumName(o.field)}, ${o.targetValue})`
                )
                .join(",\n");
            kfBlocks.push(`         {
             ${kf.time_ms}u,
             ${kf.override_count}u,
             {
${ko},
             },
         }`);
        }
        blocks.push(`    {Face::Expression::${verbName},
     ${tab.loop_duration_ms}u,
     ${tab.keyframe_count}u,
     {
${kfBlocks.join(",\n")},
     }}`);
    }
    return `#define KO(F, V) KeyframeOverride{(uint8_t)(F), (int16_t)(V), 100}
static constexpr VerbTimeline kVerbTimelines[] = {
${blocks.join(",\n")},
};
#undef KO`;
}

function emitMotion(config: FaceConfigState): string {
    const lines = config.motion.map((m, i) => {
        const name = config.expressions[i]!;
        const mode = MotionMode[m.mode];
        return `    /* ${name} */ {MotionMode::${mode}, ${m.center}, ${m.amplitude}, ${m.period_ms}, ${m.period_jitter_ms}, ${m.slew_ms}}`;
    });
    return `static constexpr ExprMotionRow kMotion[(uint8_t)Face::Expression::Count] = {\n${lines.join(",\n")},\n};`;
}

function emitIdleAnim(config: FaceConfigState): string {
    const lines = config.idleAnim.map((row, i) => {
        const name = config.expressions[i]!;
        return `    /* ${name} */ ${emitIdleAnimRowCpp(row)}`;
    });
    return `static constexpr IdleAnimRow kIdleAnim[(uint8_t)Face::Expression::Count] = {\n${lines.join(",\n")},\n};`;
}

function emitIdleAnimRowCpp(row: IdleAnimRow): string {
    const gaze = GazeStyle[row.gaze_style];
    return `{${row.blink_period_min_ms}, ${row.blink_period_max_ms}, ${row.blink_close_ms}, ${row.blink_open_ms}, ${bobAmpCppLiteral(row.bob_amplitude_px)}, GazeStyle::${gaze}, ${row.gaze_move_ms}, ${row.gaze_rand_span_x}, ${row.gaze_rand_span_y}, ${row.gaze_reroll_min_ms}, ${row.gaze_reroll_max_ms}, ${row.gaze_scan_period_ms}, ${row.gaze_amp_x}, ${row.gaze_amp_y}}`;
}

function emitEmotionSim(config: FaceConfigState): string {
    const s = config.emotionSim;
    return `static constexpr EmotionSimConfig kEmotionSim = {
    ${s.tau_ms_activation}f,  // tau_ms_activation
    ${s.tau_ms_valence}f, // tau_ms_valence
    ${s.tau_ms_raw_follow}f,    // tau_ms_raw_follow
    ${s.snap_hysteresis_dist}f,    // snap_hysteresis_dist
    ${s.snap_hysteresis_hold_ms},      // snap_hysteresis_hold_ms
    ${s.dist_sq_tie_eps}f,    // dist_sq_tie_eps
    ${s.baseline_activation}f,     // baseline_activation
};`;
}

function emitFrameAnim(config: FaceConfigState): string {
    const f = config.frameAnim;
    return `static constexpr FrameAnimConfig kFrameAnim = {
    ${f.mood_ring_tau_ms}f, // mood_ring_tau_ms
    ${f.emotion_geometry_smooth_tau_ms}f, // emotion_geometry_smooth_tau_ms
    ${f.tick_interval_ms},     // tick_interval_ms
    ${f.tick_interval_stream_ms},     // tick_interval_stream_ms
    ${f.thinking_flip_dur_ms},    // thinking_flip_dur_ms
    ${f.thinking_flip_min_ms},    // thinking_flip_min_ms
    ${f.thinking_flip_max_ms},    // thinking_flip_max_ms
    ${f.progress_fade_ms},    // progress_fade_ms
    ${f.effects_fade_ms},    // effects_fade_ms
    ${f.breath_period_ms},   // breath_period_ms
    ${f.breath_eye_amp_px}f,   // breath_eye_amp_px
    ${f.breath_mouth_scale}f,   // breath_mouth_scale
    ${f.emotion_bob_amp_follow_arm},      // emotion_bob_amp_follow_arm
    ${f.default_blink_close_ms},     // default_blink_close_ms
    ${f.default_blink_open_ms},     // default_blink_open_ms
    ${f.default_gaze_move_ms},     // default_gaze_move_ms
    ${f.invalid_gaze_reroll_fallback_ms},   // invalid_gaze_reroll_fallback_ms
};`;
}

export function emitFaceConfigH(config: FaceConfigState): string {
    const emotionPointLines = config.emotionPoints.map((p, i) => {
        const name = namedEmotionEnumName(config.emotionNames[i]!);
        return `    {${fmtCppFloat(p.v)}, ${fmtCppFloat(p.a)}},    // ${name}`;
    });

    const baseTargetLines = config.baseTargets.map((row, i) =>
        emitFacePRowCpp(config.expressions[i]!, row)
    );

    const armLines = config.armPresets.map((p, i) => {
        const name = config.expressions[i]!;
        return `    {${p.min_deg}, ${p.max_deg}, ${p.period_s}f, ${p.interval_s}f},   // ${name}`;
    });

    const emotionNameLine =
        "    " +
        config.emotionNames.map(n => `"${n}"`).join(", ") +
        ",";

    const isEmotionLine =
        "    " +
        config.expressionIsEmotion.map(b => (b ? "true" : "false")).join(", ") +
        ",";

    return `${FACE_ENUM_PREAMBLE}

${emitExpressionNames(config.expressions)}

static constexpr bool kExpressionIsEmotion[(size_t)Face::Expression::Count] = {
${isEmotionLine}
};

static constexpr const char* kEmotionNames[(size_t)EmotionSystem::NamedEmotion::Count] = {
${emotionNameLine}
};

struct EmotionPoint {
  float v;
  float a;
};

static constexpr EmotionPoint kEmotionPoints[(size_t)EmotionSystem::NamedEmotion::Count] = {
${emotionPointLines.join("\n")}
};

/// Tie-break when two anchors are equidistant (earlier wins).
${emitPickOrder(config)}

${emitNamedEmotionToExpression(config)}

#ifndef FACE_P
#define FACE_P(V) ::Face::ParamI16{ (int16_t)(V), 100 }
#endif
static const Face::FaceParams kBaseTargets[(uint8_t)Face::Expression::Count] = {
${baseTargetLines.join("")}
};
#undef FACE_P

static constexpr uint8_t kVerbKeyframeOverridesMax = ${config.verbKeyframeOverridesMax};
static constexpr uint8_t kVerbKeyframesMax = ${config.verbKeyframesMax};

struct KeyframeOverride {
  uint8_t field;
  int16_t targetValue;
  uint8_t strength;
};

struct VerbKeyframe {
  uint32_t time_ms;
  uint8_t override_count;
  KeyframeOverride overrides[kVerbKeyframeOverridesMax];
};

struct VerbTimeline {
  Face::Expression verb;
  uint32_t loop_duration_ms;
  uint8_t keyframe_count;
  VerbKeyframe keyframes[kVerbKeyframesMax];
};

${emitVerbTimelines(config)}

struct ArmPreset {
  int8_t min_deg;
  int8_t max_deg;
  float period_s;
  float interval_s;
};

static constexpr ArmPreset kArmPresets[(uint8_t)Face::Expression::Count] = {
${armLines.join("\n")}
};

enum class MotionMode : uint8_t {
  None = 0,
  Static,
  RandomDrift,
  Oscillate,
  Waggle,
  Thinking,
};

struct ExprMotionRow {
  MotionMode mode;
  int8_t center;
  uint8_t amplitude;
  uint16_t period_ms;
  uint16_t period_jitter_ms;
  uint16_t slew_ms;
};

${emitMotion(config)}

inline constexpr int16_t kBobAmpFollowEmotionArm = (int16_t)(0x8000);

enum class GazeStyle : uint8_t {
  Off = 0,
  IdleRandom,
  Orbit,
  ScanX,
};

struct IdleAnimRow {
  uint16_t blink_period_min_ms;
  uint16_t blink_period_max_ms;
  uint16_t blink_close_ms;
  uint16_t blink_open_ms;
  int16_t bob_amplitude_px;
  GazeStyle gaze_style;
  uint16_t gaze_move_ms;
  int16_t gaze_rand_span_x;
  int16_t gaze_rand_span_y;
  uint32_t gaze_reroll_min_ms;
  uint32_t gaze_reroll_max_ms;
  uint32_t gaze_scan_period_ms;
  int16_t gaze_amp_x;
  int16_t gaze_amp_y;
};

${emitIdleAnim(config)}

struct EmotionSimConfig {
  float tau_ms_activation;
  float tau_ms_valence;
  float tau_ms_raw_follow;
  float snap_hysteresis_dist;
  uint32_t snap_hysteresis_hold_ms;
  float dist_sq_tie_eps;
  float baseline_activation;
};

struct FrameAnimConfig {
  float mood_ring_tau_ms;
  float emotion_geometry_smooth_tau_ms;
  uint32_t tick_interval_ms;
  uint32_t tick_interval_stream_ms;
  uint32_t thinking_flip_dur_ms;
  uint32_t thinking_flip_min_ms;
  uint32_t thinking_flip_max_ms;
  uint32_t progress_fade_ms;
  uint32_t effects_fade_ms;
  uint32_t breath_period_ms;
  float breath_eye_amp_px;
  float breath_mouth_scale;
  int16_t emotion_bob_amp_follow_arm;
  uint16_t default_blink_close_ms;
  uint16_t default_blink_open_ms;
  uint16_t default_gaze_move_ms;
  uint32_t invalid_gaze_reroll_fallback_ms;
};

${emitEmotionSim(config)}

${emitFrameAnim(config)}

struct VerbSimConfig {
  uint32_t strain_delay_ms;
  uint32_t default_overlay_duration_ms;
};

struct MotionRuntimeConfig {
  uint16_t default_static_slew_ms;
  uint16_t default_drift_slew_ms;
};

static constexpr VerbSimConfig kVerbSim = {
    ${config.verbSim.strain_delay_ms}, // strain_delay_ms
    ${config.verbSim.default_overlay_duration_ms}, // default_overlay_duration_ms
};

static constexpr MotionRuntimeConfig kMotionRuntime = {
    ${config.motionRuntime.default_static_slew_ms}, // default_static_slew_ms
    ${config.motionRuntime.default_drift_slew_ms}, // default_drift_slew_ms
};

static_assert(sizeof(kMotion) / sizeof(kMotion[0]) == (uint8_t)Face::Expression::Count,
              "kMotion rows must match Face::Expression::Count");
static_assert(sizeof(kIdleAnim) / sizeof(kIdleAnim[0]) == (uint8_t)Face::Expression::Count,
              "kIdleAnim rows must match Face::Expression::Count");

}  // namespace FaceConfig
`;
}
